INSERT INTO INT_SERVERFUNCTION (ID, NAME, DESCRIPTION, TYPE, CODE, JDBC_ID, PUBLIC_EXECUTION, CRON_EXPRESSION, CRON_INPUT_JSON, CREATED_BY) VALUES (116, 'hotPkgCrOrcamento', 'ORCAMENTO por CR/mes do pacote (por nome do driver).', 'SQL', 'SELECT CR_ID, MES, SUM(VALOR) as VALOR FROM ORCAMENTO
     WHERE CICLO_ID = {{cicloId}} AND DRIVER_TIPO = (SELECT NOME FROM DRIVERS WHERE ID = {{pkgId}}) GROUP BY CR_ID, MES', NULL, FALSE, NULL, NULL, 'sarah@mitralab.io');
